using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using ARO.NetCore;
using Xunit;

/// <summary>
/// The two E5 engine TEST routes (Assets/_Project/Resources/Routes/ng-kano-e5-*.route.json, generated by tools/e5/gen_e5_routes.py): six roundabout designs on a chain, and the flagship interchange F1
/// (a ground roundabout under a dual expressway deck, with an off ramp and an on ramp). Fictional layouts for the engine; nothing in them is approved for production.
/// </summary>
public class KanoE5RouteTests
{
    public static RouteSpec Load(string id) => JsonSerializer.Deserialize<RouteSpec>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, id + ".route.json")), Fx.Opt);
    static RouteModel _rb, _f1;
    public static RouteModel Roundabouts => _rb ??= RouteModel.Build(Load("ng-kano-e5-roundabouts"));
    public static RouteModel F1 => _f1 ??= RouteModel.Build(Load("ng-kano-e5-f1"));
    static ISet<string> KnownProps() => new HashSet<string>(Fx.LoadCatalog().props.Select(p => p.id));

    [Fact] public void BothRoutesPassTheValidatorWithTheShippedPropCatalog()
    {
        foreach (var id in new[] { "ng-kano-e5-roundabouts", "ng-kano-e5-f1" })
            Assert.True(RouteSpecValidator.Validate(Load(id), KnownProps()).Count == 0, id + ":\n" + string.Join("\n", RouteSpecValidator.Validate(Load(id), KnownProps())));
    }

    [Fact] public void BothRoutesBuild()
    {
        Assert.Equal(6, Roundabouts.Rings.Count);
        Assert.Single(F1.Rings);
        Assert.True(F1.HasLevels);
    }
}

public class KanoE5SweptPathTests
{
    // Wheel overrun limits (metres a wheel may stand outside the pavement at a mouth, on the dropped kerb or the walkway edge). The bus is the game's placeholder: 10 m long on an 8.2 m wheelbase.
    static float WheelLimit(DesignVehicle v) => v == DesignVehicle.Car ? 1.0f : v == DesignVehicle.TruckLight ? 1.2f : v == DesignVehicle.TruckMedium ? 1.5f : 2.4f;

    static IEnumerable<(RouteModel m, Roundabout r)> AllRings() => KanoE5RouteTests.Roundabouts.Rings.Select(r => (KanoE5RouteTests.Roundabouts, r)).Concat(KanoE5RouteTests.F1.Rings.Select(r => (KanoE5RouteTests.F1, r)));

    [Fact] public void EveryVehicleDrivesEveryEntryToEveryExitOfEverySevenDesignsWithoutStrikingAnything()
    {
        var fails = new List<string>(); int sims = 0;
        foreach (var (m, ring) in AllRings())
            foreach (var v in DesignVehicle.All)
                foreach (var entry in ring.Legs)
                    foreach (var exit in ring.Legs)
                    {
                        if (entry.CorridorId == exit.CorridorId) continue;
                        var res = SweptPath.Drive(m, v, SweptPath.RingPath(m, ring, entry, exit, ring.Lanes - 1, 1, v.EasyTurnRadius)); sims++;
                        string tag = ring.Id + " " + v.Name + " " + entry.CorridorId + " -> " + exit.CorridorId;
                        if (!res.Reached) fails.Add(tag + ": " + res.Why);
                        else if (res.MaxSteerDeg > v.MaxSteerDeg) fails.Add(tag + ": needs " + res.MaxSteerDeg.ToString("0.0") + " degrees of steering (limit " + v.MaxSteerDeg + ")");
                        else if (res.StruckMetres > 0.01f) fails.Add(tag + ": the body hits the island or leaves the road for " + res.StruckMetres.ToString("0.0") + " m");
                        else if (res.WheelDepth > WheelLimit(v)) fails.Add(tag + ": a wheel goes " + res.WheelDepth.ToString("0.0") + " m outside the pavement (limit " + WheelLimit(v) + ")");
                    }
        Assert.Equal(142 * 4, sims);                                                      // 142 entry/exit pairs over the seven rings, four vehicles each
        Assert.True(fails.Count == 0, fails.Count + " of " + sims + " paths fail:\n" + string.Join("\n", fails.Take(25)));
    }

    [Fact] public void TheSevenDesignsAreDifferentInTheirShapeNotJustTheirSize()
    {
        var all = AllRings().Select(x => x.r).ToList();
        Assert.Equal(7, all.Count);
        var sig = all.Select(r => (r.Spec.design, r.Lanes, r.Legs.Count, r.Spec.island, r.Section.HasKerb, r.Spec.apron > 0f, r.Spec.flare > 0f, (int)(r.Spec.radius / 4))).ToList();
        Assert.Equal(7, sig.Select(x => x.design).Distinct().Count());
        Assert.Equal(7, sig.Distinct().Count());
        Assert.True(all.Select(r => r.Legs.Count).Distinct().Count() >= 4, "leg counts: " + string.Join(",", all.Select(r => r.Legs.Count)));      // 3, 4, 5, 6, 7 ...
        Assert.True(all.Select(r => r.Spec.island).Distinct().Count() >= 4);                                                                           // paved, planter, earth, grass
        Assert.Contains(all, r => r.Lanes == 4); Assert.Contains(all, r => !r.Section.HasKerb); Assert.Contains(all, r => r.Spec.radius <= 15f); Assert.Contains(all, r => r.Spec.radius >= 38f);
    }

    [Fact] public void EveryIslandHoldsItsPropsAndEveryRingHasStreetLights()
    {
        var m = KanoE5RouteTests.Roundabouts;
        var inst = PropScatter.PlaceChunk(m, -2000f, -2000f, 6000f, 2000f);
        foreach (var r in m.Rings)
        {
            Assert.True(inst.Count(i => i.Origin != null && i.Origin.StartsWith(r.Id + "/")) == r.Spec.props.Length, r.Id + " island props");
            Assert.All(inst.Where(i => i.Origin != null && i.Origin.StartsWith(r.Id + "/")), i => Assert.Equal(r.Island.TopY, i.Pos.Y, 3));
            Assert.True(inst.Count(i => i.Origin != null && i.Origin.StartsWith(r.Id + "_light")) >= 6, r.Id + " lights");
        }
    }

    [Fact] public void TheSeamOfEveryRingIsRoadNotTheEndOfOne()
    {
        foreach (var (m, r) in AllRings())
        {
            float a = r.SToAngle(0f);                                                      // the seam of the circle
            foreach (float d in new[] { r.CentreRadius + 2.0f, r.CentreRadius - 2.0f })
            {
                float x = r.Cx + d * (float)Math.Cos(a), z = r.Cz + d * (float)Math.Sin(a);
                Assert.True(m.Terrain.InsideRoadAlong(x, z, -0.5f), r.Id + " seam, ring " + d);
                Assert.True(m.IsPaved(x, z), r.Id + " seam paved " + d);
                Assert.True(Math.Abs(r.Corridor.SurfaceY(0f, d - r.CentreRadius) - m.GroundHeight(x, z)) < 0.05f, r.Id + " seam ground " + m.GroundHeight(x, z) + " vs " + r.Corridor.SurfaceY(0f, d - r.CentreRadius));
            }
            float xo = r.Cx + (r.CentreRadius + 3.2f) * (float)Math.Cos(a + 0.001f), zo = r.Cz + (r.CentreRadius + 3.2f) * (float)Math.Sin(a + 0.001f);
            Assert.True(m.Terrain.InsideFormation(xo, zo));
        }
    }

    [Fact] public void BuildingTheRoutesTwiceGivesTheSameWorld()
    {
        foreach (var id in new[] { "ng-kano-e5-roundabouts", "ng-kano-e5-f1" })
        {
            var a = RouteModel.Build(KanoE5RouteTests.Load(id)); var b = RouteModel.Build(KanoE5RouteTests.Load(id));
            Assert.Equal(Digest(a), Digest(b));
        }
    }

    /// <summary>A digest of everything the world is made of: road meshes, ring and island meshes, terrain, ground heights and props, over the whole route.</summary>
    public static string Digest(RouteModel m)
    {
        var h = new System.Text.StringBuilder(); const float Chunk = 200f;
        var chunks = new SortedSet<(int, int)>();
        foreach (var c in m.AllCorridors) for (int i = 0; i < c.RingS.Length; i++) chunks.Add(((int)Math.Floor(c.RingX[i] / Chunk), (int)Math.Floor(c.RingZ[i] / Chunk)));
        foreach (var (cx, cz) in chunks)
        {
            float x0 = cx * Chunk, z0 = cz * Chunk; var org = new V3(x0, 0, z0);
            foreach (var c in m.AllCorridors) Mesh(h, c.Id, RoadGeometry.BuildChunk(c, x0, z0, x0 + Chunk, z0 + Chunk, org, (x, z) => m.Terrain.HeightAt(x, z)));
            foreach (var r in m.Rings) Mesh(h, r.Id + "/ring", RingGeometry.BuildChunk(r, x0, z0, x0 + Chunk, z0 + Chunk, org, id => m.CorridorById(id)));
            Mesh(h, "terrain", TerrainGeometry.BuildTile(m.Terrain, x0, z0, Chunk, 20, org, true, true));
            foreach (var p in PropScatter.PlaceChunk(m, x0, z0, x0 + Chunk, z0 + Chunk, 1f)) h.Append(p.Prop).Append(p.Origin).Append(Math.Round(p.Pos.X, 2)).Append(Math.Round(p.Pos.Y, 2)).Append(Math.Round(p.Pos.Z, 2)).Append(Math.Round(p.YawDeg, 1));
        }
        for (float s = 0; s < m.Main.Length; s += 7f) { m.Main.Spline.FrameAt(s, out var pos, out _, out var right); foreach (float off in new[] { -12f, 0f, 12f, 40f }) { float x = pos.X + right.X * off, z = pos.Z + right.Z * off; h.Append(Math.Round(m.GroundHeight(x, z), 3)).Append(Math.Round(m.Terrain.HeightAt(x, z), 3)); } }
        using (var sha = System.Security.Cryptography.SHA256.Create()) return string.Concat(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(h.ToString())).Select(b => b.ToString("x2")));
    }
    static void Mesh(System.Text.StringBuilder h, string id, MeshBuffers mb)
    {
        h.Append(id).Append(':').Append(mb.VertexCount).Append('/'); foreach (var t in mb.Triangles) h.Append(t.Count).Append(',');
        foreach (var v in mb.Vertices) h.Append(Math.Round(v.X, 3)).Append(Math.Round(v.Y, 3)).Append(Math.Round(v.Z, 3));
    }

    static string RepoRoot() { var d = new DirectoryInfo(AppContext.BaseDirectory); while (d != null && !File.Exists(Path.Combine(d.FullName, "CLAUDE.md"))) d = d.Parent; return d?.FullName; }

    [Fact] public void TheRoutesKeepTheNumbersTheyHadWhenE5WasMade()
    {
        var path = Path.Combine(RepoRoot(), "tests", "NetCore.Tests", "golden", "e5_routes.json");
        var now = new Dictionary<string, string> { ["ng-kano-e5-roundabouts"] = Digest(KanoE5RouteTests.Roundabouts), ["ng-kano-e5-f1"] = Digest(KanoE5RouteTests.F1) };
        if (Environment.GetEnvironmentVariable("GOLDEN_REGEN") == "1") { File.WriteAllText(path, JsonSerializer.Serialize(now, new JsonSerializerOptions { WriteIndented = true }) + "\n"); return; }
        Assert.True(File.Exists(path), "golden/e5_routes.json missing: GOLDEN_REGEN=1 dotnet test --filter KanoE5SweptPath (only for a deliberate change)");
        var want = JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(path));
        foreach (var kv in now) Assert.Equal(want[kv.Key], kv.Value);
    }
}

/// <summary>F1: the upper road (the expressway on its deck), the lower roads (the ground roundabout and its legs), and the ramps between them are all drivable on their own.</summary>
public class KanoE5F1Tests
{
    static RouteModel M => KanoE5RouteTests.F1;
    static (float x, float z, float y) At(RouteModel m, List<V2> path, int i, float nearY) { var p = path[i]; return (p.X, p.Y, m.GroundHeight(p.X, p.Y, nearY)); }

    [Fact] public void EveryVehicleDrivesTheWholeExpresswayOnTheDeckInBothDirections()
    {
        var m = M; var main = m.Main; float lane = main.Runs[0].Section.LaneCentres.Where(x => x > 0f).Min();
        foreach (var v in DesignVehicle.All)
            foreach (bool north in new[] { true, false })
            {
                var path = north ? SweptPath.LanePath(main, lane, 20f, main.Length - 20f) : SweptPath.LanePath(main, -lane, main.Length - 20f, 20f);
                var res = SweptPath.Drive(m, v, path);
                Assert.True(res.Reached, v.Name + (north ? " north: " : " south: ") + res.Why);
                Assert.True(res.StruckMetres < 0.01f && res.OverrunMetres < 0.01f, v.Name + " leaves the carriageway");
                Assert.True(res.MaxSteerDeg < 5f, v.Name + ": a straight expressway should need no steering, got " + res.MaxSteerDeg);
            }
    }

    [Fact] public void OnTheDeckTheLowestGroundIsTheRoundaboutAndTheNearestIsTheDeck()
    {
        var m = M; var main = m.Main; float lane = main.Runs[0].Section.LaneCentres.Where(x => x > 0f).Min();
        int over = 0;
        for (float s = 610f; s < 1190f; s += 7f)
        {
            main.Spline.FrameAt(s, out var pos, out _, out var right);
            float x = pos.X + right.X * lane, z = pos.Z + right.Z * lane, deck = main.SurfaceY(s, lane);
            Assert.True(main.OnDeck(s));
            Assert.Equal(deck, m.GroundHeight(x, z, deck + 0.3f), 2);                       // a vehicle on the deck stands on the deck
            float low = m.GroundHeight(x, z);                                               // the kill floor and the lamp pools see the ground
            Assert.True(low < deck - 5.5f, "ground " + low + " under the deck at " + deck + " (s=" + s + ")");
            if (Math.Abs(low - 10f) < 0.3f) over++;
        }
        Assert.True(over > 40, "the deck should run over level ground / the ring for most of its length; " + over);
    }

    [Fact] public void TheRoundaboutUnderTheDeckHasAtLeastTheMinimumHeadroomEverywhere()
    {
        var m = M; var ring = m.Rings[0]; var main = m.Main; float worst = float.MaxValue;
        for (float s = 600f; s <= 1200f; s += 2f)
        {
            main.Spline.FrameAt(s, out var pos, out _, out _);
            main.InBridge(s, out var br);
            float dist = (float)Math.Sqrt((pos.X - ring.Cx) * (pos.X - ring.Cx) + (pos.Z - ring.Cz) * (pos.Z - ring.Cz));
            if (dist < ring.OuterPavedRadius + 2f && dist > ring.Island.Radius)              // over the carriageway
            {
                float underside = pos.Y + Math.Min(main.Runs[0].Section.HeightAt(main.Runs[0].Section.PavedHalfWidth), main.Runs[0].Section.HeightAt(-main.Runs[0].Section.PavedHalfWidth)) - br.deckThickness;
                worst = Math.Min(worst, underside - ring.Corridor.SurfaceY(0f, 0f));
            }
        }
        Assert.True(worst >= RouteModel.MinClearance, "headroom " + worst);
        Assert.True(worst < float.MaxValue, "the deck must cross the ring carriageway");
    }

    [Fact] public void EveryVehicleDrivesTheLowerRoadsUnderTheDeckFromWestToEastAndEastToWest()
    {
        var m = M; var ring = m.Rings[0]; var w = ring.Legs.First(l => l.CorridorId == "hw_w"); var e = ring.Legs.First(l => l.CorridorId == "hw_e");
        foreach (var v in DesignVehicle.All)
            foreach (var (a, b) in new[] { (w, e), (e, w) })
            {
                var path = SweptPath.RingPath(m, ring, a, b, ring.Lanes - 1, 1, v.EasyTurnRadius);
                var res = SweptPath.Drive(m, v, path);
                Assert.True(res.Reached && res.StruckMetres < 0.01f, v.Name + " " + a.CorridorId + "->" + b.CorridorId + ": " + res.Why);
                // somewhere along the way the path passes under the deck, and there the ground for a vehicle at ring level is the ring, not the deck
                int under = 0;
                for (int i = 0; i < path.Count; i++)
                {
                    var p = path[i]; if (!m.Main.Spline.Nearest(p.X, p.Y, 8f, out float s, out float lat, out _) || !m.Main.OnDeck(s) || Math.Abs(lat) > 9f) continue;
                    float ground = m.GroundHeight(p.X, p.Y, 10f);
                    Assert.True(Math.Abs(ground - 10f) < 0.4f, "ground under the deck for a vehicle at ring level is " + ground);
                    under++;
                }
                Assert.True(under > 3, "the path from the west leg to the east leg passes under the deck (" + under + " samples)");
            }
    }

    [Fact] public void BothRampsAreDrivableFromTheExpresswayToTheRoundaboutAndBackByEveryVehicle()
    {
        var m = M;
        foreach (var id in new[] { "ramp_off", "ramp_on" })
        {
            var c = m.CorridorById(id); float lane = c.Runs[0].Section.LaneCentres.Where(x => x > 0f).Min();
            foreach (var v in DesignVehicle.All)
                foreach (bool forward in new[] { true, false })
                {
                    var path = forward ? SweptPath.LanePath(c, lane, 12f, c.Length - 12f) : SweptPath.LanePath(c, -lane, c.Length - 12f, 12f);
                    var res = SweptPath.Drive(m, v, path);
                    Assert.True(res.Reached && res.StruckMetres < 0.01f, id + " " + v.Name + (forward ? " forward: " : " back: ") + res.Why);
                    Assert.True(res.MaxSteerDeg <= v.MaxSteerDeg, id + " " + v.Name + " needs " + res.MaxSteerDeg + " degrees");
                    // and the climb is gentle
                    Assert.True(c.Spline.MaxGrade() <= RouteModel.MaxRampGrade, id + " grade " + c.Spline.MaxGrade());
                }
        }
        // the ramps end where they should: the off ramp starts on the expressway's edge at the height of its surface and ends on the ring at ring height; the on ramp the other way round
        var off = m.CorridorById("ramp_off"); var on = m.CorridorById("ramp_on"); var ring = m.Rings[0]; var main = m.Main;
        Assert.True(Math.Abs(off.Spline.PositionAt(0f).Y - main.SurfaceY(560f, main.Runs[0].Section.PavedHalfWidth)) < 0.1f);
        Assert.True(Math.Abs(off.Spline.PositionAt(off.Length).Y - 10f) < 0.1f);
        Assert.True(Math.Abs(on.Spline.PositionAt(0f).Y - 10f) < 0.1f);
        Assert.True(Math.Abs(on.Spline.PositionAt(on.Length).Y - main.SurfaceY(1370f, main.Runs[0].Section.PavedHalfWidth)) < 0.15f);
    }

    [Fact] public void TheGroundUnderTheDeckIsTerrainAndNotCutAwayAndTheRoadsBelowStayCut()
    {
        var m = M; var ring = m.Rings[0];
        // beside the ring, under the deck, no road: natural ground (about 10 m), not raised to the deck
        float h = m.Terrain.HeightAt(0f, -130f);
        Assert.True(Math.Abs(h - 10f) < 1.0f, "terrain under the deck is " + h);
        Assert.False(m.Terrain.InsideRoadAlong(0f, -130f, -1f));
        // the ring road under the deck is cut away for its own mesh
        Assert.True(m.Terrain.InsideRoadAlong(0f, -ring.CentreRadius, -0.5f));
        Assert.True(Math.Abs(m.Terrain.HeightAt(0f, -ring.CentreRadius) - (ring.Corridor.SurfaceY(0f, 0f) - TerrainModel.SinkUnderRoad)) < 0.4f);
        // where the expressway climbs on its embankment the terrain follows it
        var p = m.Main.Spline.PositionAt(450f);
        Assert.True(p.Y > 12f && Math.Abs(m.Terrain.HeightAt(p.X, p.Z) - (p.Y - TerrainModel.SinkUnderRoad)) < 0.7f);
    }

    [Fact] public void NoPierStandsOnTheRingOrItsLegsAndTheDeckHasPiersWhereTheGroundIsFree()
    {
        var m = M; var main = m.Main; float w = 600f;
        var mb = RoadGeometry.BuildChunk(main, -w, -w, w, w, new V3(0, 0, 0), (x, z) => m.Terrain.HeightAt(x, z));
        int footings = 0;
        foreach (var (n, c) in Fx.Tris(mb, RoadSub.Concrete))
        {
            if (c.Y > 11.5f || c.Y < 7f) continue;                                           // pier faces: low down
            bool onRoad = false;
            foreach (var o in m.AllCorridors)
            {
                if (o == main || !o.Spline.Nearest(c.X, c.Z, o.MaxFormationHalf + 1f, out float s, out float lat, out _) || o.IsEnd(s)) continue;
                if (Math.Abs(lat) <= o.HalfFormationAt(s)) onRoad = true;
            }
            Assert.False(onRoad, "a pier face at " + c.X + ", " + c.Z + " stands on a road");
            footings++;
        }
        Assert.True(footings > 20, "the deck should have piers: " + footings);
    }
}
